import React, { useState, useEffect } from 'react';
import { 
  Box, Typography, Paper, Button, Divider,
  Card, CardMedia, List, ListItem, ListItemIcon, ListItemText
} from '@mui/material';
import InteractiveExample from './InteractiveExample';
import QuizQuestion from './QuizQuestion';
import MiniChallenge from './MiniChallenge';
import SchoolIcon from '@mui/icons-material/School';
import LightbulbIcon from '@mui/icons-material/Lightbulb';
import CheckCircleOutlineIcon from '@mui/icons-material/CheckCircleOutline';

const LessonContent = ({ lesson, courseId, lessonId, onComplete }) => {
  const [completed, setCompleted] = useState(false);
  const [showQuiz, setShowQuiz] = useState(false);
  const [quizCompleted, setQuizCompleted] = useState(false);
  const [challengeCompleted, setChallengeCompleted] = useState(false);
  
  // Verificar si la lección ya está completada
  useEffect(() => {
    const checkCompletion = () => {
      try {
        const completedLessons = JSON.parse(
          localStorage.getItem(`course_${courseId}_completed_lessons`) || '[]'
        );
        return completedLessons.includes(lessonId);
      } catch (error) {
        console.error('Error checking lesson completion:', error);
        return false;
      }
    };
    
    setCompleted(checkCompletion());
  }, [courseId, lessonId]);
  
  const handleComplete = () => {
    setCompleted(true);
    if (onComplete && typeof onComplete === 'function') {
      onComplete();
    }
  };
  
  const handleQuizComplete = () => {
    setQuizCompleted(true);
    if (!completed) {
      handleComplete();
    }
  };
  
  const handleChallengeComplete = () => {
    setChallengeCompleted(true);
    if (!completed && !lesson.quiz) {
      handleComplete();
    }
  };

  // Función para renderizar contenido enriquecido basado en el tipo de lección
  const renderEnhancedContent = () => {
    // Si es la primera lección de un curso, mostrar una introducción más detallada
    if (lessonId.endsWith('-l1') || lessonId.endsWith('lesson-1')) {
      return (
        <>
          <Box sx={{ mb: 4, p: 3, bgcolor: 'primary.light', borderRadius: 2, color: 'white' }}>
            <Typography variant="h6" gutterBottom>
              ¿Por qué es importante este tema?
            </Typography>
            <Typography variant="body1" paragraph>
              {lesson.title.includes('Finanzas Personales') ? 
                'Las finanzas personales son la base de tu estabilidad económica. Entender cómo manejar tu dinero te permite tomar decisiones informadas, reducir estrés financiero y construir un futuro próspero.' :
                'Dominar este tema te dará herramientas prácticas para mejorar tu situación financiera y alcanzar tus metas económicas con mayor facilidad.'}
            </Typography>
            
            <Typography variant="h6" gutterBottom sx={{ mt: 2 }}>
              Lo que aprenderás:
            </Typography>
            <List dense>
              {[
                'Conceptos fundamentales que te ayudarán a entender mejor el tema',
                'Estrategias prácticas que podrás aplicar inmediatamente',
                'Herramientas para tomar mejores decisiones financieras',
                'Cómo evitar errores comunes en este ámbito'
              ].map((item, index) => (
                <ListItem key={index}>
                  <ListItemIcon sx={{ minWidth: 36, color: 'white' }}>
                    <CheckCircleOutlineIcon fontSize="small" />
                  </ListItemIcon>
                  <ListItemText primary={item} />
                </ListItem>
              ))}
            </List>
          </Box>
        </>
      );
    }
    return null;
  };
  
  return (
    <Box>
      {/* Contenido mejorado para inicio de lecciones */}
      {renderEnhancedContent()}
      
      {/* Contenido principal */}
      <Paper sx={{ p: 3, mb: 3 }}>
        {/* Añadir un ícono educativo al inicio */}
        <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
          <SchoolIcon color="primary" sx={{ mr: 1 }} />
          <Typography variant="subtitle1" fontWeight="bold">
            Contenido educativo
          </Typography>
        </Box>
        
        <Typography variant="body1" paragraph>
          {lesson.content}
        </Typography>
        
        {/* Añadir consejos prácticos después del contenido principal */}
        <Box sx={{ mt: 3, mb: 3, p: 2, bgcolor: 'background.paper', borderLeft: '4px solid', borderColor: 'primary.main' }}>
          <Box sx={{ display: 'flex', alignItems: 'center', mb: 1 }}>
            <LightbulbIcon color="primary" sx={{ mr: 1 }} />
            <Typography variant="subtitle1" fontWeight="bold">
              Consejo práctico
            </Typography>
          </Box>
          <Typography variant="body2">
            {lesson.title.includes('Presupuesto') ? 
              'Recuerda que un presupuesto efectivo debe ser realista y flexible. Comienza rastreando tus gastos durante un mes para tener una imagen clara de tus hábitos financieros.' :
            lesson.title.includes('Ahorro') ?
              'Automatiza tus ahorros configurando transferencias automáticas a tu cuenta de ahorro el mismo día que recibes tu sueldo. Lo que no ves, no lo gastas.' :
            lesson.title.includes('Inversión') ?
              'Antes de invertir, asegúrate de tener un fondo de emergencia equivalente a 3-6 meses de gastos. Esto te dará tranquilidad y evitará que tengas que retirar tus inversiones en momentos inoportunos.' :
            lesson.title.includes('Deuda') ?
              'Prioriza el pago de deudas con altas tasas de interés. Por cada peso que pagas en estas deudas, ahorras ese interés que de otra forma tendrías que pagar.' :
              'Aplica lo aprendido en esta lección a tu situación personal. La educación financiera cobra valor cuando la pones en práctica en tu vida diaria.'}
          </Typography>
        </Box>
        
        {lesson.type === 'video' && lesson.videoUrl && (
          <Box sx={{ my: 3, position: 'relative', paddingTop: '56.25%' }}>
            <iframe
              style={{
                position: 'absolute',
                top: 0,
                left: 0,
                width: '100%',
                height: '100%',
                border: 0
              }}
              src={lesson.videoUrl}
              title={lesson.title}
              allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
              allowFullScreen
            />
          </Box>
        )}
        
        {lesson.image && (
          <Card sx={{ my: 3 }}>
            <CardMedia
              component="img"
              height="300"
              image={lesson.image}
              alt={lesson.title}
              loading="lazy"
            />
          </Card>
        )}
        
        {!completed && !lesson.quiz && !lesson.interactive && !lesson.challenge && (
          <Box sx={{ mt: 3 }}>
            <Button 
              variant="contained" 
              color="primary"
              onClick={handleComplete}
            >
              Marcar como completado
            </Button>
          </Box>
        )}
      </Paper>
      
      {/* Ejemplo interactivo */}
      {lesson.interactive && (
        <Paper sx={{ p: 3, mb: 3 }}>
          <Typography variant="h6" gutterBottom>
            Actividad interactiva
          </Typography>
          <Divider sx={{ mb: 2 }} />
          
          <InteractiveExample 
            data={lesson.interactive} 
            lessonId={lessonId}
            onComplete={handleComplete}
          />
        </Paper>
      )}
      
      {/* Mini desafío */}
      {lesson.challenge && (
        <Box sx={{ mb: 3 }}>
          <Typography variant="h6" gutterBottom>
            Mini desafío
          </Typography>
          <Divider sx={{ mb: 2 }} />
          
          <MiniChallenge 
            data={lesson.challenge} 
            completed={challengeCompleted}
            onComplete={handleChallengeComplete}
          />
        </Box>
      )}
      
      {/* Quiz */}
      {lesson.quiz && (
        <Paper sx={{ p: 3, mb: 3 }}>
          {!showQuiz ? (
            <Box sx={{ textAlign: 'center', py: 2 }}>
              <Typography variant="h6" gutterBottom>
                ¿Listo para poner a prueba tus conocimientos?
              </Typography>
              <Button 
                variant="contained" 
                color="primary"
                onClick={() => setShowQuiz(true)}
                sx={{ mt: 2 }}
              >
                Comenzar quiz
              </Button>
            </Box>
          ) : (
            <>
              <Typography variant="h6" gutterBottom>
                Quiz: {lesson.title}
              </Typography>
              <Divider sx={{ mb: 2 }} />
              
              <QuizQuestion 
                questions={lesson.quiz.questions} 
                completed={quizCompleted}
                onComplete={handleQuizComplete}
              />
            </>
          )}
        </Paper>
      )}
    </Box>
  );
};

export default LessonContent;